import com.sun.net.httpserver.*;
import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.sql.*;import java.time.*;import java.util.*;import java.util.regex.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;

public class Server {
 static final Path WEB=Path.of("web").toAbsolutePath().normalize();
 static final SecureRandom RANDOM=new SecureRandom();
 static String env(String k,String d){String v=System.getenv(k);return v==null||v.isBlank()?d:v;}
 static Connection db()throws SQLException{return DriverManager.getConnection("jdbc:mysql://127.0.0.1:3306/carenest?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC",env("CARENEST_DB_USER","root"),env("CARENEST_DB_PASSWORD",""));}
 static String escape(String s){if(s==null)return "";StringBuilder b=new StringBuilder();for(char c:s.toCharArray()){switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}}return b.toString();}
 static String q(String s){return "\""+escape(s)+"\"";}
 static String obj(String... fields){return "{"+String.join(",",fields)+"}";}
 static String kv(String k,String v){return q(k)+":"+q(v);}
 static String number(String k,long n){return q(k)+":"+n;}
 static String get(String json,String name){Matcher m=Pattern.compile("\\\""+Pattern.quote(name)+"\\\"\\s*:\\s*\\\"((?:\\\\.|[^\\\"\\\\])*)\\\"").matcher(json);if(!m.find())return "";String s=m.group(1);StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='\\'&&i+1<s.length()){char n=s.charAt(++i);if(n=='u'&&i+4<s.length()){try{b.append((char)Integer.parseInt(s.substring(i+1,i+5),16));i+=4;}catch(Exception e){b.append('?');}}else b.append(switch(n){case 'n'->'\n';case 't'->'\t';case 'r'->'\r';default->n;});}else b.append(c);}return b.toString().trim();}
 static void send(HttpExchange e,int code,String json)throws IOException{byte[] b=json.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(code,b.length);try(OutputStream o=e.getResponseBody()){o.write(b);}}
 static void error(HttpExchange e,int code,String msg)throws IOException{send(e,code,obj(kv("error",msg)));}
 static String body(HttpExchange e)throws IOException{return new String(e.getRequestBody().readNBytes(12000),StandardCharsets.UTF_8);}
 static String hash(String password)throws Exception{byte[] salt=new byte[16];RANDOM.nextBytes(salt);return "pbkdf2:"+Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(derive(password,salt));}
 static byte[] derive(String p,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,210000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
 static boolean matches(String p,String stored)throws Exception{String[] f=stored.split(":");if(f.length!=3||!f[0].equals("pbkdf2"))return false;return MessageDigest.isEqual(derive(p,Base64.getDecoder().decode(f[1])),Base64.getDecoder().decode(f[2]));}
 static String token(HttpExchange e){String c=e.getRequestHeaders().getFirst("Cookie");if(c==null)return "";for(String v:c.split(";")){v=v.trim();if(v.startsWith("carenest_session="))return v.substring(17);}return "";}
 static Long uid(HttpExchange e)throws SQLException{String t=token(e);if(!t.matches("[a-f0-9]{64}"))return null;try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT user_id FROM sessions WHERE token_hash=SHA2(?,256) AND expires_at>NOW()")){p.setString(1,t);try(ResultSet r=p.executeQuery()){return r.next()?r.getLong(1):null;}}}
 static void createSession(HttpExchange e,long uid)throws SQLException{byte[] b=new byte[32];RANDOM.nextBytes(b);StringBuilder t=new StringBuilder();for(byte v:b)t.append(String.format("%02x",v&255));try(Connection c=db();PreparedStatement p=c.prepareStatement("INSERT INTO sessions (user_id,token_hash,expires_at) VALUES (?,SHA2(?,256),DATE_ADD(NOW(),INTERVAL 30 DAY))")){p.setLong(1,uid);p.setString(2,t.toString());p.executeUpdate();}e.getResponseHeaders().add("Set-Cookie","carenest_session="+t+"; Path=/; Max-Age=2592000; HttpOnly; SameSite=Lax");}
 static String userJson(ResultSet r)throws SQLException{return obj(number("id",r.getLong("id")),kv("fullName",r.getString("full_name")),kv("email",r.getString("email")),kv("dob",r.getString("dob")),kv("gender",r.getString("gender")),kv("phone",r.getString("phone")),kv("address",r.getString("address")),kv("role",r.getString("role")));}
 static void api(HttpExchange e)throws IOException{
  String route=e.getRequestURI().getPath().substring(5),method=e.getRequestMethod();
  try{
   if(route.equals("register")&&method.equals("POST")){String j=body(e);String name=get(j,"fullName"),email=get(j,"email").toLowerCase(Locale.ROOT),pw=get(j,"password"),dob=get(j,"dob"),role=get(j,"role").toLowerCase(Locale.ROOT);if(role.isBlank())role="patient";if(!List.of("patient","doctor","admin","accountant").contains(role)){error(e,400,"Select a valid account role.");return;}if(name.isBlank()||name.length()>120||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||pw.length()<8){error(e,400,"Provide a name, valid email, and password of at least 8 characters.");return;}LocalDate date;try{date=LocalDate.parse(dob);}catch(Exception ex){error(e,400,"Invalid date of birth.");return;}int age=Period.between(date,LocalDate.now()).getYears();if(age<18||age>124){error(e,400,"Account holder must be 18 or older.");return;}
    try(Connection c=db();PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,dob,gender,email,phone,address,password_hash,role) VALUES (?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setDate(2,java.sql.Date.valueOf(date));p.setString(3,get(j,"gender"));p.setString(4,email);p.setString(5,get(j,"phone"));p.setString(6,get(j,"address"));p.setString(7,hash(pw));p.setString(8,role);try{p.executeUpdate();}catch(SQLIntegrityConstraintViolationException ex){error(e,409,"Email already registered. Please log in.");return;}try(ResultSet r=p.getGeneratedKeys()){r.next();long id=r.getLong(1);createSession(e,id);send(e,201,obj(q("user")+":"+obj(number("id",id),kv("fullName",name),kv("email",email),kv("role",role))));}}return;}
   if(route.equals("login")&&method.equals("POST")){String j=body(e);String role=get(j,"role").toLowerCase(Locale.ROOT);if(!List.of("patient","doctor","admin","accountant").contains(role)){error(e,400,"Select your role.");return;}try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT id,password_hash,role FROM users WHERE email=?")){p.setString(1,get(j,"email").toLowerCase(Locale.ROOT));try(ResultSet r=p.executeQuery()){if(!r.next()||!matches(get(j,"password"),r.getString("password_hash"))){error(e,401,"Incorrect email or password.");return;}if(!role.equals(r.getString("role"))){error(e,403,"This account is registered as "+r.getString("role")+". Please select the correct role.");return;}long id=r.getLong("id");createSession(e,id);send(e,200,obj(q("user")+":"+obj(number("id",id),kv("role",role))));}}return;}
   if(route.equals("logout")&&method.equals("POST")){String t=token(e);if(t.matches("[a-f0-9]{64}")){try(Connection c=db();PreparedStatement p=c.prepareStatement("DELETE FROM sessions WHERE token_hash=SHA2(?,256)")){p.setString(1,t);p.executeUpdate();}}e.getResponseHeaders().add("Set-Cookie","carenest_session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax");send(e,200,"{\"ok\":true}");return;}
   Long id=uid(e);if(id==null){error(e,401,"Please log in first.");return;}
   if(route.equals("me")&&method.equals("GET")){try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT id,full_name,email,dob,gender,phone,address,role FROM users WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(r.next())send(e,200,obj(q("user")+":"+userJson(r)));else error(e,401,"Account missing.");}}return;}
   if(route.equals("appointments")){try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT role FROM users WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!"patient".equals(r.getString(1))){error(e,403,"Patient account required.");return;}}}}
   if(route.equals("appointments")&&method.equals("GET")){List<String> list=new ArrayList<>();try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT id,doctor,specialization,appointment_date,appointment_time,reason,status FROM appointments WHERE user_id=? ORDER BY appointment_date DESC,id DESC")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())list.add(obj(number("id",r.getLong("id")),kv("doctor",r.getString("doctor")),kv("specialization",r.getString("specialization")),kv("date",r.getString("appointment_date")),kv("time",r.getString("appointment_time")),kv("reason",r.getString("reason")),kv("status",r.getString("status"))));}}send(e,200,"{\"appointments\":["+String.join(",",list)+"]}");return;}
   if(route.equals("appointments")&&method.equals("POST")){String j=body(e);String doctor=get(j,"doctor"),specialization=get(j,"specialization"),date=get(j,"date"),time=get(j,"time"),reason=get(j,"reason");if(doctor.isBlank()||specialization.isBlank()||date.isBlank()||time.isBlank()||reason.isBlank()||doctor.length()>200||specialization.length()>200||reason.length()>500){error(e,400,"Complete all appointment fields.");return;}LocalDate day;try{day=LocalDate.parse(date);}catch(Exception ex){error(e,400,"Invalid date.");return;}if(day.isBefore(LocalDate.now())){error(e,400,"Choose a future date.");return;}try(Connection c=db();PreparedStatement p=c.prepareStatement("INSERT INTO appointments(user_id,doctor,specialization,appointment_date,appointment_time,reason,status) VALUES(?,?,?,?,?,?,'Pending')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,id);p.setString(2,doctor);p.setString(3,specialization);p.setDate(4,java.sql.Date.valueOf(day));p.setString(5,time);p.setString(6,reason);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();send(e,201,obj(q("appointment")+":"+obj(number("id",r.getLong(1)),kv("doctor",doctor),kv("specialization",specialization),kv("date",date),kv("time",time),kv("reason",reason),kv("status","Pending"))));}}return;}
   error(e,404,"Unknown API route.");
  }catch(SQLException ex){System.err.println("MySQL error: "+ex.getMessage());error(e,503,"MySQL connection failed. Start MySQL and import schema.sql; check database credentials in START_CARENEST.bat.");}catch(Exception ex){System.err.println("Request error: "+ex);error(e,500,"Server error: "+ex.getClass().getSimpleName());}
 }
 static void staticFile(HttpExchange e)throws IOException{String path=URLDecoder.decode(e.getRequestURI().getPath(),StandardCharsets.UTF_8);if(path.equals("/"))path="/index.html";Map<String,String> restricted=Map.of("/patient-dashboard.html","patient","/doctor-dashboard.html","doctor","/admin.html","admin","/accountant.html","accountant");String needed=restricted.get(path);if(needed!=null){try{Long id=uid(e);if(id==null){e.getResponseHeaders().set("Location","/login.html");e.sendResponseHeaders(302,-1);e.close();return;}try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT role FROM users WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!needed.equals(r.getString(1))){error(e,403,"You cannot access this dashboard with your account role.");return;}}}}catch(SQLException ex){error(e,503,"Database unavailable.");return;}}Path file=WEB.resolve(path.substring(1)).normalize();if(!file.startsWith(WEB)||!Files.isRegularFile(file)){e.sendResponseHeaders(404,-1);e.close();return;}String ext=path.contains(".")?path.substring(path.lastIndexOf('.')+1):"";String mime=switch(ext){case "html"->"text/html";case "css"->"text/css";case "js"->"application/javascript";case "svg"->"image/svg+xml";case "png"->"image/png";case "jpg","jpeg"->"image/jpeg";default->"application/octet-stream";};byte[] b=Files.readAllBytes(file);e.getResponseHeaders().set("Content-Type",mime+"; charset=utf-8");e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.sendResponseHeaders(200,b.length);try(OutputStream o=e.getResponseBody()){o.write(b);}}
 public static void main(String[] args)throws Exception{Class.forName("com.mysql.cj.jdbc.Driver");try(Connection c=db()){try(Statement st=c.createStatement()){try(ResultSet rs=c.getMetaData().getColumns(c.getCatalog(),null,"users","role")){if(!rs.next()){st.executeUpdate("ALTER TABLE users ADD COLUMN role VARCHAR(20) NOT NULL DEFAULT 'patient'");System.out.println("Updated existing users table with roles.");}}}System.out.println("Connected to MySQL database carenest.");}catch(SQLException e){System.err.println("ERROR connecting to MySQL: "+e.getMessage());System.err.println("Start MySQL and import schema.sql, then retry.");return;}HttpServer h=HttpServer.create(new InetSocketAddress("127.0.0.1",8080),0);h.createContext("/api/",Server::api);h.createContext("/",Server::staticFile);h.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(12));h.start();System.out.println("CareNest running at http://localhost:8080/  (keep this window open)");}
}
